function countOpen(tickets: readonly Ticket[]): number { return tickets.filter(t => t.status === "OPEN").length; }
console.log(countOpen([{ status: "OPEN" }, { status: "CLOSED" }]));

type Ticket = { priority: "LOW" | "MEDIUM" | "HIGH" | "CRITICAL" };
function countUrgent(tickets: readonly Ticket[]): number { return tickets.filter(t => t.priority === "HIGH" || t.priority === "CRITICAL").length; }
console.log(countUrgent([{ priority: "HIGH" }, { priority: "LOW" }, { priority: "CRITICAL" }]));

type Ticket = { assignee: string | null };
function countMine(tickets: readonly Ticket[], currentUser: string): number { return tickets.filter(t => t.assignee === currentUser).length; }
console.log(countMine([{ assignee: "anna" }, { assignee: null }, { assignee: "jan" }], "anna"));

