type Ticket = { id: number; status: "OPEN" | "IN_PROGRESS" | "CLOSED"; priority: "LOW" | "MEDIUM" | "HIGH" | "CRITICAL"; assignee: string | null };
type CardProps = { label: string; value: number; hint?: string };
function StatCard({ label, value, hint = "" }: CardProps) { return <article className="stat-card"><span>{label}</span><strong>{value}</strong>{hint.length > 0 && <small>{hint}</small>}</article>; }
export function Dashboard({ tickets, currentUser }: { tickets: readonly Ticket[]; currentUser: string }) {
  const open = tickets.filter(t => t.status === "OPEN").length;
  const urgent = tickets.filter(t => t.priority === "HIGH" || t.priority === "CRITICAL").length;
  const mine = tickets.filter(t => t.assignee === currentUser).length;
  return <div className="stats-row"><StatCard label="Otwarte" value={open}/><StatCard label="Pilne" value={urgent} hint="HIGH i CRITICAL"/><StatCard label="Moje" value={mine}/></div>;
}
